'use client'

import { useEffect, useRef } from 'react'
import { usePathname } from 'next/navigation'

export function ViewTransitions({ children }: { children: React.ReactNode }) {
  const pathname = usePathname()
  const previousPathname = useRef(pathname)

  useEffect(() => {
    if (!document.startViewTransition) return

    const handleViewTransition = (e: Event) => {
      const customEvent = e as CustomEvent<{ navigateTo: string }>
      const destination = customEvent.detail?.navigateTo

      if (destination && document.startViewTransition) {
        document.startViewTransition(() => {
          previousPathname.current = pathname
          return
        })
      }
    }

    document.addEventListener('navigate', handleViewTransition)
    return () => document.removeEventListener('navigate', handleViewTransition)
  }, [pathname])

  return <>{children}</>
}

