  from {
    transform: translateX(-30px);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes slide-out-to-right {
  from {
    transform: translateX(0);
    opacity: 1;
  }
  to {
    transform: translateX(30px);
    opacity: 0;
  }
}

@keyframes skeleton-enter {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes skeleton-exit {
  from {
    opacity: 1;
    transform: scale(1);
  }
  to {
    opacity: 0;
    transform: scale(1.05);
  }
}

::view-transition-old(root) {
  animation: 300ms cubic-bezier(0.4, 0, 0.2, 1) both slide-out-to-left;
}

::view-transition-new(root) {
  animation: 300ms cubic-bezier(0.4, 0, 0.2, 1) both slide-in-from-right;
}

::view-transition-old(product-image) {
  animation: 400ms cubic-bezier(0.4, 0, 0.2, 1) both fade-out;
}

::view-transition-new(product-image) {
  animation: 400ms cubic-bezier(0.4, 0, 0.2, 1) both fade-in;
}

::view-transition-old(skeleton-info),
::view-transition-new(skeleton-info) {
  animation: 250ms cubic-bezier(0.4, 0, 0.2, 1) both;
}

::view-transition-old(skeleton-info) {
  animation-name: skeleton-exit;
}

::view-transition-new(skeleton-info) {
  animation-name: skeleton-enter;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  ::view-transition-old(root),
  ::view-transition-new(root),
  ::view-transition-old(product-image),
  ::view-transition-new(product-image),
  ::view-transition-old(skeleton-info),
  ::view-transition-new(skeleton-info) {
    animation: none !important;
  }
}

@media (prefers-reduced-motion: no-preference) {
  html {
    scroll-behavior: smooth;
  }
}

